function n(){return[{title:"模型ID",dataIndex:"id",width:90},{title:"模型名称",dataIndex:"name",width:120},{title:"模型版本",dataIndex:"version",width:120},{title:"模型描述",dataIndex:"description",width:180,customRender:({text:t})=>t||"--"},{title:"创建时间",dataIndex:"created_at",width:120,customRender:({text:t})=>a(t)},{title:"更新时间",dataIndex:"updated_at",width:120,customRender:({text:t})=>a(t)},{width:90,title:"操作",dataIndex:"action"}]}function d(){return{labelWidth:80,baseColProps:{span:6},schemas:[{field:"name",label:"模型名称",component:"Input"},{field:"status",label:"状态",component:"Select",componentProps:{options:[{label:"未部署",value:0},{label:"已部署",value:1},{label:"已下线",value:3}]}}]}}function a(t){if(!t)return"--";const e=new Date(t);return e.toLocaleDateString()+" "+e.toLocaleTimeString()}export{n as getBasicColumns,d as getFormConfig};
